 */
export function _catchError(error, vnode) {
	if (typeof _catchError._impl == 'function') {
		return _catchError._impl(error, vnode);
	}
	throw error;
}

/**
 * Hook item fields consulted while invoking effect cleanups.
 * @param {object} hook
 */
export function HookBinding(hook) {
	this.hook = hook || null;
	this.cleanup = hook ? hook._cleanup : undefined;
	this.factory = hook ? hook._factory : undefined;
	this.reducer = hook ? hook._reducer : undefined;
}

_catchError.HookBinding = HookBinding;

